const K="pordee_v4_current", H="pordee_v4_history";
let cur=JSON.parse(localStorage.getItem(K)||"null"), hist=JSON.parse(localStorage.getItem(H)||"[]");
let d=new Date();document.getElementById("date").textContent=d.getDate()+" "+["ม.ค.","ก.พ.","มี.ค.","เม.ย.","พ.ค.","มิ.ย.","ก.ค.","ส.ค.","ก.ย.","ต.ค.","พ.ย.","ธ.ค."][d.getMonth()];
function day(){return d.getFullYear()+"-"+(d.getMonth()+1)+"-"+d.getDate()}
function hash(s){let h=2166136261;for(let c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function pick(pos){let c=Number(sessionStorage.getItem("pordee_test_count")||0)+1;sessionStorage.setItem("pordee_test_count",c);let seed=hash(day()+"-"+pos+"-"+c+"-"+Math.random());cur={...CARDS[seed%CARDS.length],date:day(),reviewed:false};localStorage.setItem(K,JSON.stringify(cur));document.getElementById("deckPanel").style.display="none";render(cur,true)}
function render(x,scroll){document.getElementById("daily").style.display="block";document.getElementById("num").textContent="TODAY • CARD "+String(x.id).padStart(3,"0");["title","body","mind","question","shareTitle","shareBody"].forEach(id=>document.getElementById(id).textContent=x[id]);if(scroll)document.getElementById("daily").scrollIntoView({behavior:"smooth",block:"start"})}
function wrapText(ctx,text,maxWidth){
  const paragraphs=String(text).split(/\n/), lines=[];
  for(const p of paragraphs){
    if(!p){lines.push("");continue}
    const chars=[...p];
    let line="";
    for(const ch of chars){
      const test=line+ch;
      if(ctx.measureText(test).width>maxWidth && line){lines.push(line);line=ch}
      else line=test;
    }
    if(line)lines.push(line);
  }
  return lines;
}
function rr(ctx,x,y,w,h,r){
  ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.closePath();
}
async function makeShareCardFile(){
  const canvas=document.createElement("canvas");
  canvas.width=1080;canvas.height=1350;
  const ctx=canvas.getContext("2d");

  const g=ctx.createLinearGradient(0,0,1080,1350);
  g.addColorStop(0,"#f7d8c9");
  g.addColorStop(.52,"#f6e8c5");
  g.addColorStop(1,"#d8e8dc");
  ctx.fillStyle=g;ctx.fillRect(0,0,1080,1350);

  ctx.fillStyle="rgba(255,253,248,.94)";
  rr(ctx,65,65,950,1220,50);ctx.fill();
  ctx.strokeStyle="rgba(117,96,67,.26)";ctx.lineWidth=3;
  rr(ctx,95,95,890,1160,36);ctx.stroke();

  ctx.textAlign="center";
  ctx.fillStyle="#9a8358";
  ctx.font='58px system-ui,-apple-system,"Noto Sans Thai",Tahoma,sans-serif';
  ctx.fillText("♡",540,220);

  ctx.fillStyle="#263b33";
  ctx.font='700 74px system-ui,-apple-system,"Noto Sans Thai",Tahoma,sans-serif';
  let y=360;
  for(const line of wrapText(ctx,cur.shareTitle,800)){ctx.fillText(line,540,y);y+=90}

  y+=35;
  ctx.fillStyle="#4f5d56";
  ctx.font='500 49px system-ui,-apple-system,"Noto Sans Thai",Tahoma,sans-serif';
  for(const line of wrapText(ctx,cur.shareBody,760)){ctx.fillText(line,540,y);y+=70}

  ctx.fillStyle="#7a817d";
  ctx.font='700 30px system-ui,-apple-system,"Noto Sans Thai",Tahoma,sans-serif';
  ctx.fillText("ส่งต่อจาก “พอดี”",540,1125);
  ctx.font='500 27px system-ui,-apple-system,"Noto Sans Thai",Tahoma,sans-serif';
  for(const [i,line] of wrapText(ctx,"ถ้าการ์ดนี้ทำให้คุณนึกถึงใคร ส่งต่อให้เขาได้เลย",760).entries()){
    ctx.fillText(line,540,1175+i*42);
  }

  const blob=await new Promise(res=>canvas.toBlob(res,"image/png",1));
  return new File([blob],"pordee-card.png",{type:"image/png"});
}
async function shareCard(){
  try{
    const file=await makeShareCardFile();
    if(navigator.canShare && navigator.canShare({files:[file]}) && navigator.share){
      await navigator.share({title:cur.shareTitle,files:[file]});
    }else{
      const a=document.createElement("a");
      a.href=URL.createObjectURL(file);
      a.download="pordee-card.png";
      a.click();
      setTimeout(()=>URL.revokeObjectURL(a.href),1500);
      toast("อุปกรณ์นี้แชร์ไฟล์ตรงไม่ได้ จึงสร้างภาพการ์ดให้แทน");
    }
  }catch(e){
    if(e && e.name==="AbortError") return;
    toast("ยังส่งภาพไม่ได้บนเบราว์เซอร์นี้");
  }
}
async function copyText(){await navigator.clipboard.writeText(cur.shareTitle+"\n\n"+cur.shareBody+"\n\n♡ ส่งต่อจาก พอดี");toast("คัดลอกแล้ว")}
function review(v){cur.done=v;if(v)document.getElementById("feels").style.display="block";else finish("ยังไม่ได้ทำ")}
function finish(f){
  cur.feeling=f;cur.reviewed=true;hist.push(cur);
  localStorage.setItem(H,JSON.stringify(hist));
  localStorage.removeItem(K);
  cur=null;
  document.getElementById("feels").style.display="none";
  document.getElementById("next").style.display="inline-block";
  toast("ขอบคุณสำหรับคำตอบ เปิดใบใหม่ได้เลย");
}
function showDeck(){
  document.getElementById("prev").style.display="none";
  document.getElementById("daily").style.display="none";
  document.getElementById("deckPanel").style.display="block";
  document.getElementById("next").style.display="none";
  window.scrollTo({top:0,behavior:"smooth"});
}
function toast(t){let x=document.getElementById("toast");x.textContent=t;x.classList.add("on");setTimeout(()=>x.classList.remove("on"),1600)}
function testNext(){
  // Test mode: no once-per-day lock, but always review the previous card first.
  if(cur){
    document.getElementById("daily").style.display="none";
    document.getElementById("deckPanel").style.display="none";
    document.getElementById("prev").style.display="block";
    document.getElementById("prevAction").textContent="กาย: "+cur.body+" • ใจ: "+cur.mind;
    document.getElementById("feels").style.display="none";
    document.getElementById("next").style.display="none";
    cur.reviewed=false;
    localStorage.setItem(K,JSON.stringify(cur));
    window.scrollTo({top:0,behavior:"smooth"});
    toast("ก่อนเปิดใบใหม่ ขอถามถึงใบเมื่อกี้นิดหนึ่ง");
  }else{
    showDeck();
  }
}

function bindEvents(){
  const done=document.getElementById("reviewDone");
  if(done) done.addEventListener("click",()=>review(true));
  const notDone=document.getElementById("reviewNotDone");
  if(notDone) notDone.addEventListener("click",()=>review(false));
  document.querySelectorAll("[data-feel]").forEach(b=>b.addEventListener("click",()=>finish(b.dataset.feel)));
  const openNext=document.getElementById("openNext");
  if(openNext) openNext.addEventListener("click",showDeck);
  document.querySelectorAll("[data-pick]").forEach(b=>b.addEventListener("click",()=>pick(Number(b.dataset.pick))));
  const share=document.getElementById("shareImage");
  if(share) share.addEventListener("click",shareCard);
  const copy=document.getElementById("copyTextBtn");
  if(copy) copy.addEventListener("click",copyText);
  const test=document.getElementById("testNextBtn");
  if(test) test.addEventListener("click",testNext);
}

function boot(){document.getElementById("deckPanel").style.display="block";document.getElementById("prev").style.display="none";document.getElementById("daily").style.display="none";}
bindEvents();
boot();
